You are an expert mathematical physicist. Your task is to provide a thorough and correct proof for a physics problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematical physicist.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\section{System Model and Problem Definition}
We consider a globally hyperbolic spacetime $(M, g_{ab})$.
Let $U$ be a small neighborhood of $p \in M$ in which
$g_{ab}|_U \approx \eta_{ab}$ (local inertial frame).
Let $\xi^a$ be the approximate boost Killing field, null on the null
hypersurfaces $\mathcal{H}_A$, $\mathcal{H}_B$ intersecting on a spacelike
$2$-surface $\mathcal{S}$: an approximate bifurcate Killing horizon
(local Rindler horizon).
We use double-null coordinates $(U, V)$; $s$ denotes coordinates on
$\mathcal{S}$.

\subsection{Algebraic Quantum Field Theory on the Horizon}

We consider a real, minimally coupled Klein-Gordon field $\Phi$ satisfying
\begin{equation}
(\Box_g + m^2)\Phi = 0. \label{eq:klein_gordon}
\end{equation}
Let $\mathscr{W}_{\mathcal{R}}$ be the Weyl algebra on the horizon portion
$\mathcal{H}_B^{\mathcal{R}}$, with symplectic form
\begin{equation}
\sigma(\phi, \psi) = \int_{\mathcal{H}_B^{\mathcal{R}}}
(\phi \, \partial_U \psi - \psi \, \partial_U \phi) \,
dU \, d\mathrm{vol}_{\mathcal{S}}, \label{eq:symplectic}
\end{equation}
and let $\mathscr{N}_{\mathcal{R}} = \pi_0(\mathscr{W}_{\mathcal{R}})''$ be the
associated von Neumann algebra in the vacuum representation.

\begin{lemma}[Summers-Verch] \label{lemma:modular}
The modular group of $(\mathscr{N}_{\mathcal{R}}, \Omega_0)$ acts geometrically
as dilations along $\mathcal{H}_B^{\mathcal{R}}$,
\begin{equation}
\Delta_{\mathcal{R}}^{it} = \mathfrak{D}_{2\pi t}, \label{eq:modular}
\end{equation}
so the restricted vacuum is a KMS state at inverse temperature
$\beta = 2\pi/\kappa$.
\end{lemma}

\begin{lemma}[Araki-Uhlmann for coherent states] \label{lemma:araki_uhlmann}
For a coherent excitation $\omega_\phi$ of the vacuum $\omega_0$,
\begin{equation}
S^{\mathrm{rel}}(\omega_0 \| \omega_\phi)
= i \frac{d}{dt}\Big|_0 \langle \Omega_\phi |
\Delta_{\mathcal{R}}^{it} \Omega_\phi \rangle
= \frac{1}{2} \frac{d}{dt}\Big|_0 \sigma(\phi^t, \phi),
\label{eq:araki_uhlmann}
\end{equation}
where $\phi^t(U, s) = \phi(e^{2\pi t} U, s)$.
Evaluating the derivative,
\begin{equation}
S^{\mathrm{rel}}(\omega_0 \| \omega_\phi)
= -2\pi \int_{\mathcal{H}_B^{\mathcal{R}}}
U \, (\partial_U \phi)^2 \, dU \, d\mathrm{vol}_{\mathcal{S}}.
\label{eq:rel_entropy_explicit}
\end{equation}
This formula holds for coherent states only.
\end{lemma}

\begin{lemma}[Relative entropy as energy flux] \label{lemma:entropy_flux}
With ${:}T_{ab}{:}$ the Hadamard-normal-ordered stress-energy tensor,
\begin{equation}
\langle {:}T_{ab}{:} \rangle_{\omega_\phi} \, \xi^a \xi^b
= (\partial_U \phi)^2, \label{eq:stress_phi}
\end{equation}
hence
\begin{equation}
S^{\mathrm{rel}}(\omega_0 \| \omega_\phi)
= -2\pi \int_{\mathcal{H}_B^{\mathcal{R}}} U \,
\langle {:}T_{ab}{:} \rangle_{\omega_\phi} \, \xi^a \xi^b \,
dU \, d\mathrm{vol}_{\mathcal{S}}, \label{eq:entropy_flux}
\end{equation}
the energy flux of the coherent excitation across the horizon.
\end{lemma}

\begin{lemma}[Thermodynamic step] \label{lemma:thermo_step}
If an energy flux $\delta Q$ across a local Rindler horizon satisfies
$\delta Q \propto \delta \mathcal{A}$, with the area variation given by the
Raychaudhuri equation as
$\delta \mathcal{A} = -\int U \, R_{ab} \xi^a \xi^b \, dU \, d\mathrm{vol}$
near the bifurcation surface (where
$\theta = \sigma_{ab} = \omega_{ab} = 0$), then
\begin{equation}
R_{ab} \, \xi^a \xi^b \propto \langle T_{ab} \rangle \, \xi^a \xi^b
\qquad \text{for all null } \xi^a, \label{eq:ricci_stress}
\end{equation}
and local conservation $\nabla^a \langle T_{ab} \rangle = 0$ together with the
contracted Bianchi identity fix the trace term, yielding an equation of the
form $R_{ab} - \tfrac{1}{2} R g_{ab} + \Lambda g_{ab} \propto \langle T_{ab}
\rangle$ with $\Lambda$ constant.
\end{lemma}

********** END CONTEXT **********

********** BEGIN EVALUATION CRITERIA **********

